const { mkdtempSync, writeFileSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const path = await import('node:path');
if (!globalThis.input || typeof globalThis.input.html !== 'string') { throw new Error('Missing html input'); }
const tmpDir = mkdtempSync(path.join(tmpdir(), 'topdf-'));
const inputPath = path.join(tmpDir, 'input.html');
writeFileSync(inputPath, globalThis.input.html);
globalThis.inputPath = inputPath;
globalThis.tmpDir = tmpDir;

const mod = await import('topdf');
const fn = mod.default || mod;
let result;
try { result = await fn(globalThis.inputPath); } catch (e) { result = null; }
if (result && Buffer.isBuffer(result)) {
  globalThis.pdfBase64 = result.toString('base64');
} else {
  const { readFileSync } = await import('node:fs');
  const pdfBuffer = readFileSync(globalThis.inputPath + '.pdf');
  globalThis.pdfBase64 = pdfBuffer.toString('base64');
}
